function fib(n) {
    const phi = 1.618034;
    return Math.round(phi ** n / Math.sqrt(5));
}

console.log(fib(10));

function fib2(n) {
    if(n <= 1) return n

    return fib2(n - 1) + fib2(n - 2)
}

