function sumOfTwo(nums, target) {
    const seen = new Map();

    for(let i = 0; i < nums.length; i++) {
        const comp = target - nums[i]

        if(seen.has(comp)) {
            return [seen.get(comp), i]
        }

        seen.set(nums[i], i)
    }

    return []
}

console.log(sumOfTwo([2,3,5,6,7], 10))

function twoNumberSum(array, targetSum) {
   const seen = new Set()

   for (const num of array) {
       const match = targetSum - num

       if (seen.has(match)) {
           return [match, num]
       }

       seen.add(num)
   }

   return []
}

